public class ResourceRunnerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.List<String> log = new java.util.ArrayList<>();
        try {
            ResourceRunner.useTwo(log);
        } catch (Exception e) {
            check("useTwo throws nothing", "none", e.getClass().getSimpleName());
        }
        check("log has three entries", 3, log.size());
        check("exact log order", "[using, closed:b, closed:a]", log.toString());
        check("first entry", "using", log.isEmpty() ? "(empty log)" : log.get(0));
        check("last entry is closed:a", "closed:a",
                log.isEmpty() ? "(empty log)" : log.get(log.size() - 1));
        check("b closes before a", true,
                log.contains("closed:b") && log.contains("closed:a")
                        && log.indexOf("closed:b") < log.indexOf("closed:a"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

