class TrackedResource implements AutoCloseable {
    private final java.util.List<String> log;
    private final String name;

    TrackedResource(java.util.List<String> log, String name) {
        this.log = log;
        this.name = name;
    }

    @Override
    public void close() {
        log.add("closed:" + name);
    }
}

public class ResourceRunner {

    public static void useTwo(java.util.List<String> log) {
        try (TrackedResource a = new TrackedResource(log, "a");
             TrackedResource b = new TrackedResource(log, "b")) {
            log.add("using");
        }
    }
}
